def solve(inputs: dict) -> float:
    M = inputs['M']
    n = inputs['n']
    mod = inputs['mod']

    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices mod modulus"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, n, mod):
        """Compute M^n mod modulus using binary exponentiation"""
        if n == 1:
            return M

        result = [[1, 0], [0, 1]]  # Identity matrix
        base = [row[:] for row in M]  # Copy M

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    result = matrix_pow(M, n, mod)
    return float(sum(result[0]) + sum(result[1]))

